1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"regexp"
10		"sort"
11		"strconv"
12		"strings"
13	)
14	
15	// Point 是一条序列上某个时间戳的采样值。
16	type Point struct {
17		Timestamp int64   `json:"timestamp"`
18		Value     float64 `json:"value"`
19	}
20	
21	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
22	type SeriesView struct {
23		Name   string            `json:"name"`
24		Labels map[string]string `json:"labels"`
25		Points []Point           `json:"points"`
26	}
27	
28	// BatchResult 是一批采样点写入成功后的结果。
29	type BatchResult struct {
30		Status     string       `json:"status"`
31		Added      int          `json:"added"`
32		Duplicates int          `json:"duplicates"`
33		Series     []SeriesView `json:"series"`
34	}
35	
36	// SeriesRef 标识一条序列：指标名加完整标签集合。
37	// 缺少某个标签与该标签值为空字符串属于不同序列。
38	type SeriesRef struct {
39		Name   string            `json:"name"`
40		Labels map[string]string `json:"labels"`
41	}
42	
43	// Conflict 描述同一序列同一时间戳已存在不同的值。
44	type Conflict struct {
45		Series    SeriesRef `json:"series"`
46		Timestamp int64     `json:"timestamp"`
47		Existing  float64   `json:"existing"`
48		Submitted float64   `json:"submitted"`
49	}
50	
51	// LineError 是一行（一批）输入失败后的结构化结果。
52	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
53	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
54	type LineError struct {
55		Status   string    `json:"status"`
56		Line     int       `json:"line,omitempty"`
57		Index    int       `json:"index,omitempty"`
58		Error    string    `json:"error"`
59		Conflict *Conflict `json:"conflict,omitempty"`
60	}
61	
62	// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
63	type MetricStore struct {
64		series map[seriesID]*storedSeries
65	}
66	
67	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
68	type seriesID struct {
69		name string
70		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
71		sig string
72	}
73	
74	type storedSeries struct {
75		ref    SeriesRef
76		points map[int64]float64
77	}
78	
79	// NewMetricStore 创建一个空的指标存储。
80	func NewMetricStore() *MetricStore {
81		return &MetricStore{series: make(map[seriesID]*storedSeries)}
82	}
83	
84	func sortedKeys(m map[string]string) []string {
85		keys := make([]string, 0, len(m))
86		for k := range m {
87			keys = append(keys, k)
88		}
89		sort.Strings(keys)
90		return keys
91	}
92	
93	func makeSeriesID(name string, labels map[string]string) seriesID {
94		var b strings.Builder
95		for _, k := range sortedKeys(labels) {
96			v := labels[k]
97			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
98		}
99		return seriesID{name: name, sig: b.String()}
100	}
101	
102	// labelPair 是标签键值对字典序比较的单元。
103	type labelPair struct {
104		Key, Value string
105	}
106	
107	func sortedPairs(labels map[string]string) []labelPair {
108		keys := sortedKeys(labels)
109		pairs := make([]labelPair, len(keys))
110		for i, k := range keys {
111			pairs[i] = labelPair{Key: k, Value: labels[k]}
112		}
113		return pairs
114	}
115	
116	func compareLabelPairs(a, b []labelPair) int {
117		n := len(a)
118		if len(b) < n {
119			n = len(b)
120		}
121		for i := 0; i < n; i++ {
122			if a[i].Key != b[i].Key {
123				return strings.Compare(a[i].Key, b[i].Key)
124			}
125			if a[i].Value != b[i].Value {
126				return strings.Compare(a[i].Value, b[i].Value)
127			}
128		}
129		switch {
130		case len(a) < len(b):
131			return -1
132		case len(a) > len(b):
133			return 1
134		}
135		return 0
136	}
137	
138	var (
139		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
140		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
141	)
142	
143	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
144	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
145	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
146		dec := json.NewDecoder(strings.NewReader(line))
147		var top json.RawMessage
148		if err := dec.Decode(&top); err != nil {
149			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
150		}
151		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
152		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
153			if err == nil {
154				err = fmt.Errorf("unexpected content after the JSON value")
155			}
156			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
157		}
158		trimmed := strings.TrimSpace(string(top))
159		if len(trimmed) == 0 || trimmed[0] != '[' {
160			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
161		}
162		var items []json.RawMessage
163		if err := json.Unmarshal(top, &items); err != nil {
164			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
165		}
166		return s.ingestItems(items)
167	}
168	
169	type parsedSample struct {
170		name   string
171		ts     int64
172		value  float64
173		labels map[string]string
174	}
175	
176	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
177	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
178	func parseSample(raw json.RawMessage) (parsedSample, error) {
179		var p parsedSample
180		p.labels = map[string]string{}
181		dec := json.NewDecoder(bytes.NewReader(raw))
182		dec.UseNumber()
183	
184		tok, err := dec.Token()
185		if err != nil {
186			return p, err
187		}
188		if d, ok := tok.(json.Delim); !ok || d != '{' {
189			return p, fmt.Errorf("each sample must be a JSON object")
190		}
191	
192		present := make(map[string]bool)
193		for dec.More() {
194			keyTok, err := dec.Token()
195			if err != nil {
196				return p, err
197			}
198			key := keyTok.(string)
199			switch key {
200			case "name", "timestamp", "value", "labels":
201			default:
202				return p, fmt.Errorf("unknown field %q", key)
203			}
204			if present[key] {
205				return p, fmt.Errorf("duplicate field %q", key)
206			}
207			present[key] = true
208	
209			switch key {
210			case "name":
211				t, err := dec.Token()
212				if err != nil {
213					return p, err
214				}
215				s, ok := t.(string)
216				if !ok {
217					return p, fmt.Errorf(`field "name" must be a string`)
218				}
219				if s == "" {
220					return p, fmt.Errorf(`field "name" must be a non-empty string`)
221				}
222				p.name = s
223			case "timestamp":
224				n, err := nextJSONNumber(dec, "timestamp")
225				if err != nil {
226					return p, err
227				}
228				v, err := parseJSONInt(n)
229				if err != nil {
230					return p, fmt.Errorf(`field "timestamp": %s`, err)
231				}
232				p.ts = v
233			case "value":
234				n, err := nextJSONNumber(dec, "value")
235				if err != nil {
236					return p, err
237				}
238				v, err := parseFiniteFloat(n)
239				if err != nil {
240					return p, fmt.Errorf(`field "value": %s`, err)
241				}
242				p.value = v
243			case "labels":
244				t, err := dec.Token()
245				if err != nil {
246					return p, err
247				}
248				d, ok := t.(json.Delim)
249				if !ok || d != '{' {
250					return p, fmt.Errorf(`field "labels" must be an object of string keys to string values`)
251				}
252				labels := map[string]string{}
253				for dec.More() {
254					labelKeyTok, err := dec.Token()
255					if err != nil {
256						return p, err
257					}
258					labelKey := labelKeyTok.(string)
259					if labelKey == "" {
260						return p, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
261					}
262					valTok, err := dec.Token()
263					if err != nil {
264						return p, err
265					}
266					labelVal, ok := valTok.(string)
267					if !ok {
268						return p, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
269					}
270					if _, dup := labels[labelKey]; dup {
271						return p, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
272					}
273					labels[labelKey] = labelVal
274				}
275				if _, err := dec.Token(); err != nil { // 消耗 '}'
276					return p, err
277				}
278				p.labels = labels
279			}
280		}
281		if _, err := dec.Token(); err != nil { // 消耗 '}'
282			return p, err
283		}
284		if _, err := dec.Token(); err != io.EOF {
285			if err == nil {
286				return p, fmt.Errorf("unexpected content after the sample object")
287			}
288			return p, err
289		}
290	
291		for _, field := range []string{"name", "timestamp", "value"} {
292			if !present[field] {
293				return p, fmt.Errorf("missing required field %q", field)
294			}
295		}
296		return p, nil
297	}
298	
299	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
300		t, err := dec.Token()
301		if err != nil {
302			return "", err
303		}
304		n, ok := t.(json.Number)
305		if !ok {
306			return "", fmt.Errorf(`field %q must be a JSON number`, field)
307		}
308		return n, nil
309	}
310	
311	func parseJSONInt(n json.Number) (int64, error) {
312		s := string(n)
313		if !jsonIntegerRE.MatchString(s) {
314			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
315		}
316		v, err := strconv.ParseInt(s, 10, 64)
317		if err != nil {
318			return 0, fmt.Errorf("must be within int64 range")
319		}
320		return v, nil
321	}
322	
323	func parseFiniteFloat(n json.Number) (float64, error) {
324		s := string(n)
325		if !jsonNumberRE.MatchString(s) {
326			return 0, fmt.Errorf("must be a JSON number")
327		}
328		v, err := strconv.ParseFloat(s, 64)
329		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
330			return 0, fmt.Errorf("must be a finite number representable as float64")
331		}
332		return v, nil
333	}
334	
335	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
336	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
337		type pending struct {
338			id  seriesID
339			ref SeriesRef
340			ts  int64
341			val float64
342		}
343	
344		added := 0
345		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
346		seen := make(map[seriesID]map[int64]float64)
347		// 仅记录需要落盘的新增点；校验全部通过后才提交。
348		commits := make([]pending, 0, len(items))
349	
350		failAt := func(index int, msg string) *LineError {
351			return &LineError{Status: "error", Index: index, Error: msg}
352		}
353		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
354			return &LineError{
355				Status: "error",
356				Index:  index,
357				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
358					ref, ts, formatFloat(existing), formatFloat(submitted)),
359				Conflict: &Conflict{
360					Series:    ref,
361					Timestamp: ts,
362					Existing:  existing,
363					Submitted: submitted,
364				},
365			}
366		}
367	
368		for i, item := range items {
369			pos := i + 1
370			p, err := parseSample(item)
371			if err != nil {
372				return nil, failAt(pos, err.Error())
373			}
374	
375			id := makeSeriesID(p.name, p.labels)
376			ref := SeriesRef{Name: p.name, Labels: p.labels}
377	
378			if byTS, ok := seen[id]; ok {
379				if old, ok := byTS[p.ts]; ok {
380					if old != p.value {
381						return nil, conflictAt(pos, ref, p.ts, old, p.value)
382					}
383					// 同批内重复出现且数值相同：重复，成功忽略。
384					continue
385				}
386			}
387			if sr, ok := s.series[id]; ok {
388				if old, ok := sr.points[p.ts]; ok {
389					if old != p.value {
390						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
391					}
392					// 与此前批次已写入的值相同：重复，成功忽略。
393					if seen[id] == nil {
394						seen[id] = map[int64]float64{}
395					}
396					seen[id][p.ts] = p.value
397					continue
398				}
399			}
400	
401			added++
402			if seen[id] == nil {
403				seen[id] = map[int64]float64{}
404			}
405			seen[id][p.ts] = p.value
406			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
407		}
408	
409		// 全部采样点合法且无冲突，原子提交本批新增点。
410		for _, c := range commits {
411			sr := s.series[c.id]
412			if sr == nil {
413				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
414				s.series[c.id] = sr
415			}
416			sr.points[c.ts] = c.val
417		}
418	
419		return s.snapshot(added, len(items)-added), nil
420	}
421	
422	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
423	func formatFloat(v float64) string {
424		return strconv.FormatFloat(v, 'g', -1, 64)
425	}
426	
427	// String 让冲突原因中的序列身份可读：name{k=v,...}，标签按键排序。
428	func (r SeriesRef) String() string {
429		var b strings.Builder
430		b.WriteString(r.Name)
431		b.WriteByte('{')
432		for i, p := range sortedPairs(r.Labels) {
433			if i > 0 {
434				b.WriteByte(',')
435			}
436			fmt.Fprintf(&b, "%s=%s", p.Key, p.Value)
437		}
438		b.WriteByte('}')
439		return b.String()
440	}
441	
442	// snapshot 生成按规范排序的全部序列视图：先按指标名，再按标签键值对字典序，
443	// 序列内按时间戳升序。
444	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
445		views := make([]SeriesView, 0, len(s.series))
446		for _, sr := range s.series {
447			tsList := make([]int64, 0, len(sr.points))
448			for ts := range sr.points {
449				tsList = append(tsList, ts)
450			}
451			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
452			points := make([]Point, len(tsList))
453			for i, ts := range tsList {
454				points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
455			}
456			labels := make(map[string]string, len(sr.ref.Labels))
457			for k, v := range sr.ref.Labels {
458				labels[k] = v
459			}
460			views = append(views, SeriesView{Name: sr.ref.Name, Labels: labels, Points: points})
461		}
462		sort.Slice(views, func(i, j int) bool {
463			if views[i].Name != views[j].Name {
464				return views[i].Name < views[j].Name
465			}
466			return compareLabelPairs(sortedPairs(views[i].Labels), sortedPairs(views[j].Labels)) < 0
467		})
468		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
469	}
470

